"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4498],{64498:e=>{e.exports=JSON.parse('{"slug":"samsung-rekord-pamyat-smartfony-ceny","locale":"ru","title":"Samsung заработала рекордные $80 млрд за квартал на дефиците памяти, а смартфоны дорожают","description":"Samsung получила 107,4 трлн вон операционной прибыли за III квартал 2026 года. Почему из-за памяти для ИИ дорожают смартфоны в мире и в России.","blocks":[{"id":"b001","kind":"paragraph","text":"Samsung Electronics 8 октября 2026 года оценила операционную прибыль за III квартал в 107,4 трлн вон, около $80,2 млрд. Годом раньше было 12,2 трлн вон, рост почти в 9 раз. Выручка выросла больше чем в 2 раза, примерно до 195 трлн вон. Прошлый рекорд, 89,5 трлн вон, был во II квартале 2026 года. Аналитики ждали чуть больше, около 108 трлн вон."},{"id":"b002","kind":"paragraph","text":"Рост прибыли Samsung дала память, и прежде всего память для серверов искусственного интеллекта. Её делают на тех же заводах, что и обычную память для телефонов и ноутбуков, но продают намного дороже. Похоже на пекарню, которой ресторан платит за торты в 3 раза больше, чем магазин за хлеб. Печи те же, и хлеба она печёт меньше. Новый завод строят несколько лет. Прибыль, которую завод упускает, выпуская обычную память вместо серверной, называют альтернативной стоимостью."},{"id":"b003","kind":"paragraph","text":"Мобильная память во II квартале 2026 года подорожала почти в 3 раза к IV кварталу 2025-го. С начала 2026 года в мире подорожали больше 40% моделей смартфонов, в среднем на 15%. Новинки 2026 года на 25% дороже прошлогодних. Телефонов выпускают и покупают меньше: Counterpoint Research в июне ухудшила прогноз и ждёт, что поставки смартфонов в 2026 году упадут на 13,9%, до 1,08 млрд штук. Подразделение Samsung, которое делает телефоны Galaxy, во II квартале впервые ушло в операционный убыток, 0,7 трлн вон, из-за дорогой памяти."},{"id":"b004","kind":"paragraph","text":"В России за 37 недель 2026 года продали 15,2 млн смартфонов, на 11,7% меньше, чем годом раньше. Средний чек вырос на 7,6%, до 25,8 тыс. рублей, а он зависит и от ценников, и от выбора покупателей. На памяти в дешёвых моделях экономят: у Redmi 17, вышедшего в сентябре, при цене от 18 тыс. рублей 4 ГБ оперативной памяти. За неделю с 29 сентября по 5 октября смартфоны в России подорожали на 1,1%, телевизоры на 1%. Техника импортная, а с 1 по 6 октября официальный курс доллара вырос с 83,56 до 84,93 рубля, так что недельный рост цен может идти не только от памяти."},{"id":"b005","kind":"paragraph","text":"TrendForce ждёт, что в IV квартале 2026 года контрактные цены на обычную память вырастут ещё на 10–15% к III кварталу, на флеш-память на 15–20%. Ким Джэджун, исполнительный вице-президент подразделения памяти Samsung, ждёт дефицита весь 2026 год и большую часть 2027-го, возможно до 2028-го. Глава SK hynix Квак Но Чжун назвал 2027 год, возможно, худшим для поставок памяти за всю историю отрасли."},{"id":"b006","kind":"paragraph","text":"Телефон сейчас обойдётся дороже, чем год назад. Отложить покупку можно, но сами производители ждут, что память останется дефицитной и в 2027 году. Укрепление рубля смягчит рост цен, ослабление усилит."},{"id":"b007","kind":"heading","text":"Почему дорожают смартфоны в 2026 году?"},{"id":"b008","kind":"paragraph","text":"Из-за дефицита памяти. Производители переводят заводы на дорогую память для серверов искусственного интеллекта, и обычной памяти для телефонов не хватает. Мобильная память во II квартале 2026 года подорожала почти в 3 раза к концу 2025 года, а смартфоны в мире с начала года подорожали в среднем на 15%."},{"id":"b009","kind":"heading","text":"Насколько подорожали смартфоны в России?"},{"id":"b010","kind":"paragraph","text":"За 37 недель 2026 года средняя цена купленного смартфона в России выросла на 7,6%, до 25,8 тыс. рублей, а продажи в штуках упали на 11,7%. За неделю с 29 сентября по 5 октября смартфоны подорожали на 1,1%."},{"id":"b011","kind":"heading","text":"Когда закончится дефицит памяти?"},{"id":"b012","kind":"paragraph","text":"Производители этого не обещают. В Samsung ждут дефицита весь 2026 год и большую часть 2027-го, возможно до 2028 года. Глава SK hynix назвал 2027 год, возможно, худшим для поставок памяти за всю историю отрасли."}],"sources":[{"label":"Samsung Estimates Record $80 Billion Operating Profit in Q3 2026","url":"https://sammyguru.com/samsung-estimates-record-80-billion-operating-profit-q3-2026/"},{"label":"Samsung forecasts record third-quarter profit of $80 billion as AI boom fuels chip demand","url":"https://www.cnbc.com/2026/10/08/samsung-q3-earnings.html"},{"label":"Samsung\'s quarterly profit jumped ninefold to roughly $80 billion on AI chips","url":"https://startupfortune.com/samsungs-quarterly-profit-jumped-ninefold-to-roughly-80-billion-on-ai-chips/"},{"label":"The Samsung unit behind its Galaxy phones just reported its first quarterly loss ever","url":"https://www.phonearena.com/news/samsung-mobile-experience-unit-first-quarterly-loss_id182207"},{"label":"Дальше будет хуже. В мире бесконтрольный рост цен на смартфоны","url":"https://www.cnews.ru/news/top/2026-09-04_dalshe_budet_huzhev_mire"},{"label":"Memory Crunch Freezes Smartphone Market: 2026 Shipments Seen Plunging 13.9%","url":"https://finance.biggo.com/news/o46al54B6tLPsnrZsogu"},{"label":"AI Server Demand Sustains Memory Contract Price Increases in 4Q26","url":"https://www.trendforce.com/presscenter/news/20260930-13258.html"},{"label":"Россияне стали покупать меньше смартфонов","url":"https://3dnews.ru/1149266"},{"label":"Инфляция в России с 29 сентября по 5 октября","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Samsung warns the RAM shortage will last through 2027, maybe 2028","url":"https://www.pcworld.com/article/3203764/samsung-warns-the-ram-shortage-will-last-through-2027-maybe-2028.html"},{"label":"SK Hynix Warns Memory Shortage Will Be Worst Ever in 2027","url":"https://propakistani.pk/2026/07/13/sk-hynix-warns-memory-shortage-will-be-worst-ever-in-2027/"}],"sourceBodySha256":"9109ae1c3a0a697fc17c90fd75c97bd35553c9ab1d7901b4a84036a4db6a8302"}')}}]);